steps.solution:
#include <iostream>
#include <string>
using namespace std;

int main() {
    string station = "LUNAR-BASE";
    string channel = "ALPHA";
    string full_channel = station + "/" + channel;

    cout << full_channel << endl;
    cout << full_channel.length() << endl;
    return 0;
}

